banks={}
def bank(category,text):
    rows=[t.strip() for t in text.strip().split('|') if t.strip()]
    banks[category]=[dict(id=f'prompt_{category}_{i+1:03}',category=category,text=t,tags=tags(t),contentRating='clean',minPlayers=2,maxPlayers=12,version=1) for i,t in enumerate(rows)]
def tags(t):
    t=t.lower(); result=[]
    for tag,words in {'workplace':['office','manager','work','job','meeting','museum','employee','shop','library','chef','restaurant','bakery'],'travel':['train','ferry','airport','hotel','bus','tour','journey','luggage','ticket','station'],'family':['sibling','family','parent','cousin','relative','reunion'],'celebration':['birthday','party','wedding','festival','parade','ceremony','cake','celebrat'],'mystery':['secret','mystery','missing','strange','detective','clue','locked','mysterious'],'domestic':['kitchen','garden','neighbor','home','laundry','house','roommate'],'arts':['theater','theatre','stage','music','paint','artist','dance','band','rehearsal']}.items():
        if any(w in t for w in words):result.append(tag)
    return result or ['everyday']
