relationships=[]
def rels(text,minp,maxp,roles,expand):
    for line in text.strip().split('|'):
        t=line.strip();i=len(relationships)+1
        r=dict(id=f'rel_{i:03}',premise=t,minPlayers=minp,maxPlayers=maxp,namedRoles=roles,expandableRole=expand,tags=tags(t),contentRating='clean',version=1)
        relationships.append(r)
